
.school-rules-container {
  height: 100%;
  overflow-y: auto;
  padding: 0.25rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.rules-section {
  background: var(--bg-panel);
  border: 1px solid var(--border-color);
  border-radius: 0.5rem;
  padding: 0.6rem;
}

.section-title {
  font-family: var(--font-title);
  font-size: 0.85rem;
  color: var(--user-color-primary);
  margin-bottom: 0.5rem;
  padding-bottom: 0.3rem;
  border-bottom: 1px solid rgba(255, 183, 178, 0.2);
  letter-spacing: 1px;
}

.rules-list {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.rule-item {
  display: flex;
  align-items: flex-start;
  gap: 0.5rem;
  padding: 0.35rem;
  background: rgba(255, 183, 178, 0.1);
  border-radius: 0.35rem;
}

.rule-icon {
  font-size: 1rem;
  flex-shrink: 0;
}

.rule-content {
  flex: 1;
}

.rule-title {
  font-family: var(--font-title);
  font-size: 0.75rem;
  color: var(--text-primary);
  margin-bottom: 0.15rem;
}

.rule-desc {
  font-family: var(--font-serif);
  font-size: 0.65rem;
  color: var(--text-secondary);
  line-height: 1.3;
}

.dress-code {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.35rem;
}

.dress-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.35rem 0.5rem;
  background: rgba(255, 183, 178, 0.1);
  border-radius: 0.35rem;
}

.dress-label {
  font-family: var(--font-title);
  font-size: 0.7rem;
  color: var(--user-color-primary);
}

.dress-value {
  font-family: var(--font-serif);
  font-size: 0.65rem;
  color: var(--text-primary);
}

.behavior-list {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
}

.behavior-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.3rem 0.4rem;
  background: rgba(0, 0, 0, 0.15);
  border-radius: 0.3rem;
}

.behavior-icon {
  font-size: 0.8rem;
}

.behavior-text {
  font-family: var(--font-serif);
  font-size: 0.7rem;
  color: var(--text-primary);
}
